		u, _ := readInt(in)
		v, _ := readInt(in)
		edges[u] = append(edges[u], v)
		edges[v] = append(edges[v], u)
	}
	visited := make([]bool, n+1)
	result := 1
	for i := 1; i <= n; i++ {
		if !visited[i] {
			cnt := dfs(i, edges, visited)
			if cnt > 0 {
				result = (result * cnt) % MOD
			}
		}
	}
	fmt.Println(result)
}

func dfs(u int, edges [][]int, visited []bool) int {
	visited[u] = true
	count := 1
	for _, v := range edges[u] {
		if !visited[v] {
			count += dfs(v, edges, visited)
		}
	}
	return count
}

func readInt(in *bufio.Reader) (int, error) {
	var x int
	var sign int = 1
	var c byte
	var err error
	for {
		c, err = in.ReadByte()
		if err != nil {
			return 0, err
		}
		if c == '-' {
			sign = -1
			c, err = in.ReadByte()
			if err != nil {
				return 0, err
			}
		}
		if c >= '0' && c <= '9' {
			break
		}
	}
	x = int(c - '0')
	for {
		c, err = in.ReadByte()
		if err != nil {
			break
		}
		if c < '0' || c > '9' {
			break
		}
		x = x*10 + int(c-'0')
	}
	return x * sign, nil
}
