package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 998244353

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	if n == 1 {
		fmt.Println(1)
		return
	}
	edges := make([][]int, n+1)
	for i := 0; i < n-1; i++ {
		var u, v int
		fmt.Fscan(in, &u, &v)
		edges[u] = append(edges[u], v)
		edges[v] = append(edges[v], u)
	}

	// Root the tree at 1
	parent := make([]int, n+1)
	children := make([][]int, n+1)
	stack := []int{1}
	visited := make([]bool, n+1)
	visited[1] = true
	for len(stack) > 0 {
		u := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		for _, v := range edges[u] {
			if !visited[v] {
				visited[v] = true
				parent[v] = u
				children[u] = append(children[u], v)
				stack = append(stack, v)
			}
		}
	}

	// Post-order traversal
	postOrder := []int{}
	stack = []int{1}
	visited2 := make([]bool, n+1)
	for len(stack) > 0 {
		u := stack[len(stack)-1]
		if !visited2[u] {
			visited2[u] = true
			for i := len(children[u]) - 1; i >= 0; i-- {
				stack = append(stack, children[u][i])
			}
		} else {
			postOrder = append(postOrder, u)
			stack = stack[:len(stack)-1]
		}
	}

	// dp[u][0] = number of ways when u is not matched
	// dp[u][1] = number of ways when u is matched
	dp0 := make([]int, n+1)
	dp1 := make([]int, n+1)
	for _, u := range postOrder {
		dp0[u] = 1
		dp1[u] = 0
		for _, v := range children[u] {
			// If we don't match u with v, multiply by (dp0[v] + dp1[v])
			// If we match u with v, multiply by dp0[v]
			new_dp0 := dp0[u] * (dp0[v] + dp1[v]) % MOD
			new_dp1 := (dp1[u]*(dp0[v]+dp1[v]) + dp0[u]*dp0[v]) % MOD
			dp0[u] = new_dp0
			dp1[u] = new_dp1
		}
	}

	fmt.Println((dp0[1] + dp1[1]) % MOD)
