	stack = []int{1}
	visited2 := make([]bool, n+1)
	for len(stack) > 0 {
		u := stack[len(stack)-1]
		if visited2[u] {
			postOrder = append(postOrder, u)
			stack = stack[:len(stack)-1]
			continue
		}
		visited2[u] = true
		for i := len(children[u]) - 1; i >= 0; i-- {
			v := children[u][i]
			stack = append(stack, v)
		}
	}

	// DP
	// dp[u][0] = (ways, matched)
	// dp[u][1] = (ways, matched)
	type state struct {
		ways   int
		matched bool
	}
	dp := make([][2]state, n+1)

	for _, u := range postOrder {
		if len(children[u]) == 0 {
			// Leaf node
			dp[u][0] = state{ways: 1, matched: false}
			dp[u][1] = state{ways: 0, matched: true}
		} else {
			// Initialize with first child
			c0 := children[u][0]
			// Initial state: not matched
			notMatchedWays := dp[c0][0].ways
			matchedWays := dp[c0][1].ways

			for i := 1; i < len(children[u]); i++ {
				c := children[u][i]
				newNotMatched := (notMatchedWays * (dp[c][0].ways + dp[c][1].ways)) % mod
				newMatched := (matchedWays * (dp[c][0].ways + dp[c][1].ways) + notMatchedWays * dp[c][1].ways) % mod
				notMatchedWays = newNotMatched
				matchedWays = newMatched
			}

