func readInt(in *bufio.Reader) (int, error) {
	var x int
	var c byte
	var err error
	for {
		c, err = in.ReadByte()
		if err != nil {
			return 0, err
		}
		if c == '-' {
			break
		}
		if c >= '0' && c <= '9' {
			x = x*10 + int(c-'0')
			break
		}
	}
	for {
		c, err = in.ReadByte()
		if err != nil {
			return x, err
		}
		if c < '0' || c > '9' {
			break
		}
		x = x*10 + int(c-'0')
	}
	return x, nil
}
