	// The maximum matching size is max(dp[1].not_used_size, dp[1].used_size)
	max_size := max(dp[1].not_used_size, dp[1].used_size)
	total := 0
	if dp[1].not_used_size == max_size {
		total = (total + dp[1].not_used_count) % MOD
	}
	if dp[1].used_size == max_size {
		total = (total + dp[1].used_count) % MOD
