const MOD = 998244353

func main() {
	in := bufio.NewReader(os.Stdin)
	n := readInt(in)
	if n == 1 {
		fmt.Println(1)
		return
	}
	adj := make([][]int, n+1)
	for i := 0; i < n-1; i++ {
		u := readInt(in)
		v := readInt(in)
		adj[u] = append(adj[u], v)
		adj[v] = append(adj[v], u)
	}
	// Root the tree at 1
	parent := make([]int, n+1)
	children := make([][]int, n+1)
	stack := []int{1}
	visited := make([]bool, n+1)
	visited[1] = true
	for len(stack) > 0 {
		u := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		for _, v := range adj[u] {
			if !visited[v] {
				visited[v] = true
				parent[v] = u
				children[u] = append(children[u], v)
				stack = append(stack, v)
			}
		}
	}
	// Post-order traversal
	postOrder := []int{}
	stack = []int{1}
	visited2 := make([]bool, n+1)
	for len(stack) > 0 {
		u := stack[len(stack)-1]
		if visited2[u] {
			postOrder = append(postOrder, u)
			stack = stack[:len(stack)-1]
			continue
		}
		visited2[u] = true
		for _, v := range children[u] {
			stack = append(stack, v)
		}
	}
	// dp[u][0]: number of ways when u is not matched
	// dp[u][1]: number of ways when u is matched
	dp0 := make([]int, n+1)
	dp1 := make([]int, n+1)
	for _, u := range postOrder {
		if len(children[u]) == 0 {
			dp0[u] = 1
			dp1[u] = 0
			continue
		}
		// Compute product of (dp0[v] + dp1[v]) for all children v
		prod := 1
		for _, v := range children[u] {
			prod = prod * (dp0[v] + dp1[v]) % MOD
		}
		dp0[u] = prod
		// Compute dp1[u]
		dp1[u] = 0
		for _, v := range children[u] {
			term := dp1[v] * modInverse(dp0[v]+dp1[v], MOD) % MOD
			dp1[u] = (dp1[u] + prod*term) % MOD
		}
	}
	fmt.Println((dp0[1] + dp1[1]) % MOD)
}

func readInt(in *bufio.Reader) int {
	var x int
	var c byte
	for {
		b, err := in.ReadByte()
		if err != nil {
			break
		}
		if b == '-' {
			c = '-'
			continue
		}
		if b < '0' || b > '9' {
			if c == '-' {
				break
			}
			continue
		}
		x = x*10 + int(b-'0')
	}
	if c == '-' {
		x = -x
	}
	return x
}

func modInverse(a, mod int) int {
	return pow(a, mod-2, mod)
}

func pow(a, b, mod int) int {
	res := 1
	a %= mod
	for b > 0 {
		if b&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		b >>= 1
	}
	return res
}
