	n    int
	g    [][]int
	dp0  []int // dp0[v]: number of ways when v is not matched in the unique maximum matching
	dp1  []int // dp1[v]: number of ways when v is matched in the unique maximum matching
	ans  int
)

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n)
	g = make([][]int, n+1)
	for i := 0; i < n-1; i++ {
		var u, v int
		fmt.Fscan(in, &u, &v)
		g[u] = append(g[u], v)
		g[v] = append(g[v], u)
	}

	if n == 1 {
		fmt.Println(1)
		return
	}

	dp0 = make([]int, n+1)
	dp1 = make([]int, n+1)

	// Root the tree at 1
	dfs(1, 0)

	// The answer is the number of ways where the maximum matching is unique
	// This is dp0[1] + dp1[1]
	ans = (dp0[1] + dp1[1]) % MOD
	fmt.Println(ans)
}

func dfs(v, p int) {
	// Initialize: leaf node
	dp0[v] = 1 // not matched
	dp1[v] = 0 // matched (impossible for leaf unless it has an edge to parent)

	for _, u := range g[v] {
		if u == p {
			continue
		}
		dfs(u, v)

		// For each child u, we have two states:
		// 1. Edge (v,u) is removed: child u can be in any valid state independently
		// 2. Edge (v,u) is kept: if v is matched with u, then u must be unmatched, and v cannot be matched with any other child

		new_dp0 := dp0[v] * (dp0[u] + dp1[u]) % MOD
		new_dp1 := dp1[v] * (dp0[u] + dp1[u]) % MOD

		// If we keep the edge (v,u) and match v with u:
		// v is matched, u is unmatched
		new_dp1 = (new_dp1 + dp0[v] * dp0[u]) % MOD

		dp0[v] = new_dp0
		dp1[v] = new_dp1
	}
}
