		v := readInt(reader)
		edges[u] = append(edges[u], v)
		edges[v] = append(edges[v], u)
	}

	dp0 := make([]int, n+1)
	dp1 := make([]int, n+1)
	visited := make([]bool, n+1)

	var dfs func(u int)
	dfs = func(u int) {
		visited[u] = true
