		for _, v := range edges[u] {
			if !visited[v] {
				dfs(v)
				new_dp0 := (dp0[u] * (dp0[v] + dp1[v])) % MOD
				new_dp1 := (dp1[u] * (dp0[v] + dp1[v]) + dp0[u] * dp1[v]) % MOD
				dp0[u] = new_dp0
				dp1[u] = new_dp1
			}
		}
	}

	dfs(1)
	fmt.Println((dp0[1] + dp1[1]) % MOD)
}

func readInt(reader *bufio.Reader) int {
	var x int
	var c byte
	for {
		b, err := reader.ReadByte()
		if err != nil {
			return x
		}
		if b == '-' {
			c = '-'
			continue
		}
		if b >= '0' && b <= '9' {
			x = x*10 + int(b-'0')
			if c == '-' {
				x = -x
			}
			break
		}
	}
	return x
}
